module uart_tx (
    input clk,
    input rst,
    input [7:0] data,
    input start,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000;
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [15:0] counter;
    reg [7:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // idle state
            busy <= 0;
            bit_index <= 0;
            counter <= 0;
        end else if (start && !busy) begin
            busy <= 1;
            shift_reg <= data;
            tx <= 0; // start bit
            bit_index <= 0;
            counter <= 0;
        end else if (busy) begin
            if (counter < BIT_PERIOD - 1) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                if (bit_index < 8) begin
                    tx <= shift_reg[bit_index];
                    bit_index <= bit_index + 1;
                end else if (bit_index == 8) begin
                    tx <= 1; // stop bit
                    bit_index <= bit_index + 1;
                end else begin
                    busy <= 0; // transmission complete
                    tx <= 1; // return to idle state
                end
            end
        end
    end
endmodule

