module sample_rate_converter (
    input wire clk,
    input wire rst,
    input wire [3:0] in_signal,
    output reg [3:0] out_signal
);
    reg [3:0] last_input;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            last_input <= 4'b0000;
            out_signal <= 4'b0000;
        end else begin
            last_input <= in_signal;
            if (clk) begin
                out_signal <= last_input;
            end
        end
    end
endmodule

