module butterworth_filter (
    input clk,
    input reset,
    input [15:0] data_in,
    output reg [15:0] data_out
);
    reg [15:0] coeff [0:3]; // Coefficients for the filter
    reg [15:0] state [0:3]; // States for the filter
    integer i;

    initial begin
        coeff[0] = 16'h1A; // Example coefficient values
        coeff[1] = 16'h2B;
        coeff[2] = 16'h3C;
        coeff[3] = 16'h4D;
        for (i = 0; i < 4; i = i + 1) begin
            state[i] = 16'h0;
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_out <= 16'h0;
            for (i = 0; i < 4; i = i + 1) begin
                state[i] <= 16'h0;
            end
        end else begin
            state[0] <= data_in;
            for (i = 1; i < 4; i = i + 1) begin
                state[i] <= state[i-1] * coeff[i];
            end
            data_out <= state[3];
        end
    end
endmodule

