module deserializer (
    input wire clk,
    input wire rst,
    input wire serial_in,
    output reg [15:0] parallel_out
);

reg [3:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        parallel_out <= 16'b0;
        count <= 4'b0;
    end else if (count < 16) begin
        parallel_out <= {parallel_out[14:0], serial_in};
        count <= count + 1;
    end
end

endmodule

