module deserializer (
    input wire clk,
    input wire rst,
    input wire [15:0] data_in,
    output reg [7:0] data_out,
    output reg valid
);
    reg [1:0] state;
    reg [15:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 0;
            data_out <= 8'b0;
            valid <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    shift_reg <= data_in;
                    state <= 2'b01;
                    valid <= 1'b0;
                end
                2'b01: begin
                    data_out <= shift_reg[15:8];
                    valid <= 1'b1;
                    state <= 2'b10;
                end
                2'b10: begin
                    data_out <= shift_reg[7:0];
                    valid <= 1'b1;
                    state <= 2'b00;
                end
            endcase
        end
    end
endmodule

