module serializer (
    input clk,
    input rst,
    input en,
    input [31:0] parallel_in,
    output reg serial_out
);
    reg [4:0] count; // To count the bits shifted out

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            serial_out <= 0;
        end else if (en) begin
            if (count < 32) begin
                serial_out <= parallel_in[31 - count];
                count <= count + 1;
            end
        end
    end
endmodule

