module stop_and_wait(  
    input clk,  
    input rst,  
    input [4:0] data_in,  
    input send,  
    output reg ack_out,  
    output reg [4:0] data_out  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, SEND = 2'b01, WAIT = 2'b10;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            ack_out <= 0;  
            data_out <= 5'b00000;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send) begin  
                        data_out <= data_in;  
                        state <= SEND;  
                    end  
                end  
                SEND: begin  
                    ack_out <= 0; // Initialize ACK as not received  
                    state <= WAIT;  
                end  
                WAIT: begin  
                    ack_out <= 1; // Send acknowledgment  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

