module quarter_round (  
    input  [31:0] a,  
    input  [31:0] b,  
    input  [31:0] c,  
    input  [31:0] d,  
    output reg [31:0] o_a,  
    output reg [31:0] o_b,  
    output reg [31:0] o_c,  
    output reg [31:0] o_d,  
