module bubble_sort (
    input clk,
    input rst,
    input start,
    input [15:0] data_in, // 4 unsigned 4-bit numbers
    output reg [15:0] data_out,
    output reg done
);
    reg [3:0] i, j;
    reg [15:0] arr;
    reg [3:0] state;

    parameter IDLE = 0, SORT = 1, DONE = 2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            done <= 0;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        arr <= data_in;
                        i <= 0;
                        j <= 0;
                        state <= SORT;
                    end
                end
                SORT: begin
                    if (i < 4) begin
                        if (j < 3 - i) begin
                            if (arr[4*j +: 4] > arr[4*(j+1) +: 4]) begin
                                // Swap
                                arr[4*j +: 4] <= arr[4*(j+1) +: 4];
                                arr[4*(j+1) +: 4] <= arr[4*j +: 4];
                            end
                            j <= j + 1;
                        end else begin
                            j <= 0;
                            i <= i + 1;
                        end
                    end else begin
                        data_out <= arr;
                        done <= 1;
                        state <= DONE;
                    end
                end
                DONE: begin
                    // Stay in DONE state
                end
            endcase
        end
    end
endmodule

