module kalman_filter (
    input clk,
    input rst,
    input [15:0] measurement1, // Sensor 1 measurement
    input [15:0] measurement2, // Sensor 2 measurement
    output reg [15:0] estimate_position,
    output reg [15:0] estimate_velocity
);

    reg [15:0] estimate_pos_prev;
    reg [15:0] estimate_vel_prev;
    reg [15:0] kalman_gain;

    parameter [15:0] process_noise = 16'd1; // Process noise covariance
    parameter [15:0] measurement_noise = 16'd4; // Measurement noise covariance

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            estimate_position <= 16'd0;
            estimate_velocity <= 16'd0;
            estimate_pos_prev <= 16'd0;
            estimate_vel_prev <= 16'd0;
            kalman_gain <= 16'd0;
        end else begin
            // Prediction step
            estimate_position <= estimate_pos_prev + estimate_velocity;
            estimate_velocity <= estimate_vel_prev;

            // Update step
            kalman_gain <= (process_noise) / (process_noise + measurement_noise);
            estimate_position <= estimate_position + kalman_gain * (measurement1 + measurement2 - estimate_position);
            estimate_velocity <= estimate_velocity + kalman_gain * (measurement2 - estimate_velocity);

            // Store previous estimates
            estimate_pos_prev <= estimate_position;
            estimate_vel_prev <= estimate_velocity;
        end
    end
endmodule

