module spi_slave(  
    input wire MOSI,  
    input wire SCK,  
    input wire SS,  
    output reg [7:0] MISO  
);  
    reg [7:0] shift_reg;  
    integer bit_count;  

    always @(posedge SCK or negedge SS) begin  
        if (!SS) begin  
            bit_count <= 0;  
            shift_reg <= 0;  
        end else begin  
            if (bit_count < 8) begin  
                shift_reg[bit_count] <= MOSI;  
                bit_count <= bit_count + 1;  
            end  
        end  
    end  

    always @(negedge SCK) begin  
        if (SS)  
            MISO <= shift_reg;  
    end  
endmodule

