code:
module PLL(input wire clk_in,  
           input wire data_in,  
           output reg clk_out);  

    reg [3:0] phase_detector;  
    reg [7:0] vco;  
    reg [3:0] low_pass_filter;  

    always @(posedge clk_in) begin  
        // Phase Detector Logic  
        phase_detector <= {phase_detector[2:0], data_in};  
        // Low Pass Filter Logic  
        low_pass_filter <= (low_pass_filter + phase_detector[3]) >> 1;  
        // Voltage Controlled Oscillator Logic  
        vco <= (vco + low_pass_filter) >> 1;  
        // Output the recovered clock signal  
        clk_out <= (vco[7] == 1'b1) ? ~clk_out : clk_out;  
    end  
endmodule

