module pitch_detector (  
    input clk,  
    input reset,  
    input [7:0] audio_sample,  
    output reg pitch_detected  
);  
    reg [3:0] counter;  
    parameter TARGET_FREQUENCY = 440; // Target frequency for pitch detection  
    parameter THRESHOLD = 5; // Threshold to consider it a pitch detection  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            pitch_detected <= 0;  
        end else begin  
            if (audio_sample > TARGET_FREQUENCY - THRESHOLD && audio_sample < TARGET_FREQUENCY + THRESHOLD) begin  
                counter <= counter + 1;  
                if (counter >= 10) begin  
                    pitch_detected <= 1;  
                end  
            end else begin  
                counter <= 0;  
                pitch_detected <= 0;  
            end  
        end  
    end  
endmodule

