module instruction_pipeline (
    input clk,
    input rst,
    input [4:0] instruction_in,
    output reg [4:0] instruction_if,
    output reg [4:0] instruction_id,
    output reg [4:0] instruction_ex
);

reg [4:0] pipeline_if;
reg [4:0] pipeline_id;
reg [4:0] pipeline_ex;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        pipeline_if <= 5'b0;
        pipeline_id <= 5'b0;
        pipeline_ex <= 5'b0;
        instruction_if <= 5'b0;
        instruction_id <= 5'b0;
        instruction_ex <= 5'b0;
    end else begin
        // Shift pipeline stages
        instruction_ex <= pipeline_id; // EX stage gets ID stage value
        instruction_id <= pipeline_if; // ID stage gets IF stage value
        pipeline_if <= instruction_in;  // IF stage gets new instruction
    end
end

endmodule

