module pulse_generator #(parameter PULSE_WIDTH = 10) (  
    input clk,  
    input reset,  
    input trigger,  
    output reg pulse  
);  

reg [31:0] count;  
reg generating;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        pulse <= 0;  
        count <= 0;  
        generating <= 0;  
    end else begin  
        if (trigger && !generating) begin  
            pulse <= 1;  
            count <= 0;  
            generating <= 1;  
        end else if (generating) begin  
            if (count < PULSE_WIDTH) begin  
                count <= count + 1;  
            end else begin  
                pulse <= 0;  
                generating <= 0;  
            end  
        end  
    end  
end  
endmodule

