module rsa_encrypt (
    input wire clk,
    input wire reset,
    input wire [11:0] plaintext,
    output reg [11:0] ciphertext
);
    reg [11:0] temp;
    reg [2:0] state; // State machine for encryption process
    parameter IDLE = 3'b000, COMPUTE = 3'b001, OUTPUT = 3'b010;
    parameter EXPONENT = 5;
    parameter MODULUS = 23;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            ciphertext <= 12'b0;
            temp <= 12'b0;
        end else begin
            case (state)
                IDLE: begin
                    temp <= plaintext;
                    state <= COMPUTE;
                end
                COMPUTE: begin
                    temp <= (temp ** EXPONENT) % MODULUS; // Simple exponentiation and modulus
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    ciphertext <= temp;
                    state <= IDLE; // Go back to idle
                end
            endcase
        end
    end
endmodule

