        if (pixel == 4'b0001) begin
            angle = 8'd45;     // Example angle for the detected line
            distance = 8'd100; // Example distance for the detected line
        end else if (pixel == 4'b0010) begin
            angle = 8'd90;
            distance = 8'd80;
